ta_Source ,s.sku as exception_sku FROM rpsg_db.maplemonk.ecom_flipkart_seller_report b LEFT JOIN ( select * from rpsg_DB.maplemonk.fact_items_easyecom_drv qualify row_number() over(partition by lower(reference_code),lower(sku) order by 1) = 1 )eef ON (b.\"Order ID\") = EEF.reference_code AND (LOWER(REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))) = LOWER(EEF.SKU) INNER JOIN ( select * from (select SKU, BRAND, CATEGORY, MARKETPLACE, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, row_number() over (partition by lower(sku) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where sku is not null ) where rw=1 ) S ON (LOWER(REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))) = (LOWER(S.sku)); ;",
